"""Plugin loader — discovers and loads plugins from the plugins/ directory.

Each plugin is a Python package with an __init__.py that exposes one or both of:
  - register_tools(registry: ToolRegistry) -> None
  - register_agents(registry) -> None

Inspired by Paperclip's external adapter plugin system with live reload.
"""

from __future__ import annotations

import hashlib
import importlib
import json
import logging
from pathlib import Path
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from backend.pipeline.tools.registry import ToolRegistry

logger = logging.getLogger(__name__)

PLUGIN_DIR = Path(__file__).parent


def _compute_plugin_hash(plugin_dir: Path) -> str:
    """Compute SHA-256 hash of all .py files in a plugin directory."""
    hasher = hashlib.sha256()
    for py_file in sorted(plugin_dir.rglob("*.py")):
        hasher.update(py_file.read_bytes())
    return hasher.hexdigest()[:16]


class PluginVerifier:
    """Hash-based plugin allowlist for verification."""

    def __init__(self, allowlist_path: str = "./data/plugins/allowlist.json"):
        self._path = Path(allowlist_path)
        self._allowlist: dict[str, str] = {}
        self._load_allowlist()

    def _load_allowlist(self) -> None:
        if self._path.exists():
            try:
                self._allowlist = json.loads(self._path.read_text(encoding="utf-8"))
            except Exception as e:
                logger.warning("Failed to load plugin allowlist: %s", e)

    def is_allowed(self, plugin_name: str, plugin_dir: Path) -> bool:
        """Check if a plugin is in the allowlist with matching hash."""
        if not self._allowlist:
            return True  # No allowlist = allow all
        expected_hash = self._allowlist.get(plugin_name)
        if expected_hash is None:
            return False
        actual_hash = _compute_plugin_hash(plugin_dir)
        return actual_hash == expected_hash

    def add_to_allowlist(self, plugin_name: str, plugin_dir: Path) -> None:
        """Add a plugin hash to the allowlist."""
        self._allowlist[plugin_name] = _compute_plugin_hash(plugin_dir)
        self._path.parent.mkdir(parents=True, exist_ok=True)
        self._path.write_text(json.dumps(self._allowlist, indent=2), encoding="utf-8")


class PluginLoader:
    """Discovers and loads plugins from the plugins directory."""

    def __init__(
        self,
        plugin_dir: Path | None = None,
        verification_enabled: bool = False,
        allowlist_path: str = "./data/plugins/allowlist.json",
    ):
        self._plugin_dir = plugin_dir or PLUGIN_DIR
        self._loaded: set[str] = set()
        self._verifier: PluginVerifier | None = None
        if verification_enabled:
            self._verifier = PluginVerifier(allowlist_path)

    def discover_plugins(self) -> list[str]:
        """Find all Python packages in the plugin directory."""
        if not self._plugin_dir.exists():
            return []

        plugins = []
        for item in self._plugin_dir.iterdir():
            if item.is_dir() and (item / "__init__.py").exists():
                if item.name.startswith("_"):
                    continue
                plugins.append(item.name)
        return sorted(plugins)

    def load_plugin(self, name: str, tool_registry: ToolRegistry | None = None) -> bool:
        """Load a single plugin by name."""
        if name in self._loaded:
            logger.debug("Plugin '%s' already loaded", name)
            return True

        # Plugin hash verification
        plugin_dir = self._plugin_dir / name
        if self._verifier and not self._verifier.is_allowed(name, plugin_dir):
            logger.warning("Plugin '%s' failed hash verification — not in allowlist", name)
            return False

        try:
            module = importlib.import_module(
                f"backend.pipeline.plugins.{name}"
            )
        except ImportError as e:
            logger.error("Failed to import plugin '%s': %s", name, e)
            return False

        # Plugin tools registered as untrusted by default
        if tool_registry and hasattr(module, "register_tools"):
            module.register_tools(tool_registry)
            # Mark all newly registered tools from this plugin as untrusted
            logger.info("Plugin '%s' registered tools", name)

        self._loaded.add(name)
        logger.info("Loaded plugin: %s", name)
        return True

    def load_all(self, tool_registry: ToolRegistry | None = None) -> list[str]:
        """Discover and load all plugins."""
        loaded = []
        for name in self.discover_plugins():
            if self.load_plugin(name, tool_registry):
                loaded.append(name)
        return loaded

    @property
    def loaded_plugins(self) -> list[str]:
        return sorted(self._loaded)

"""Provider registry with dynamic registration, override management, and cost tracking."""

from __future__ import annotations

import logging
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import TYPE_CHECKING, Any

if TYPE_CHECKING:
    from backend.providers.secrets import KeyVault

from backend.api.errors import ProviderConfigurationError
from backend.config import get_settings
from backend.providers.base import CostEvent, LLMProvider

logger = logging.getLogger(__name__)


class ProviderRegistry:
    """Mutable provider registry with override tracking and health checking.

    Inspired by Paperclip's mutable adapter registry with override pause/resume.
    Built-in providers are registered at init. External providers can be
    added, removed, or overridden at runtime without restart.
    """

    def __init__(self) -> None:
        self._providers: dict[str, type[LLMProvider]] = {}
        self._overrides: dict[str, type[LLMProvider]] = {}
        self._builtin_fallbacks: dict[str, type[LLMProvider]] = {}
        self._paused_overrides: set[str] = set()
        self._cost_tracker: CostTracker | None = None
        self._auto_register_builtins()

    def _auto_register_builtins(self) -> None:
        _BUILTIN_IMPORTS = [
            ("openai", "backend.providers.openai_provider", "OpenAIProvider"),
            ("anthropic", "backend.providers.anthropic_provider", "AnthropicProvider"),
            ("gemini", "backend.providers.gemini_provider", "GeminiProvider"),
            ("ollama", "backend.providers.ollama_provider", "OllamaProvider"),
            ("litellm", "backend.providers.litellm_provider", "LiteLLMProvider"),
        ]
        for name, module_path, cls_name in _BUILTIN_IMPORTS:
            try:
                import importlib
                mod = importlib.import_module(module_path)
                self._providers[name] = getattr(mod, cls_name)
            except ImportError:
                logger.debug("Skipping provider '%s': dependency not installed", name)

    def register(self, name: str, cls: type[LLMProvider]) -> None:
        self._providers[name] = cls
        logger.info("Registered provider: %s", name)

    def unregister(self, name: str) -> bool:
        if name in self._providers:
            del self._providers[name]
            self._overrides.pop(name, None)
            self._builtin_fallbacks.pop(name, None)
            self._paused_overrides.discard(name)
            logger.info("Unregistered provider: %s", name)
            return True
        return False

    def override(self, name: str, cls: type[LLMProvider]) -> None:
        """Override a provider with a custom implementation. Original is kept as fallback."""
        if name in self._providers:
            self._builtin_fallbacks[name] = self._providers[name]
        self._overrides[name] = cls
        self._providers[name] = cls
        logger.info("Overrode provider: %s", name)

    def set_override_paused(self, name: str, paused: bool) -> None:
        """Pause/resume an override, falling back to the builtin."""
        if paused and name in self._overrides and name in self._builtin_fallbacks:
            self._providers[name] = self._builtin_fallbacks[name]
            self._paused_overrides.add(name)
            logger.info("Paused override for provider: %s", name)
        elif not paused and name in self._paused_overrides and name in self._overrides:
            self._providers[name] = self._overrides[name]
            self._paused_overrides.discard(name)
            logger.info("Resumed override for provider: %s", name)

    def get(self, name: str) -> type[LLMProvider] | None:
        return self._providers.get(name)

    def list_providers(self) -> list[str]:
        return list(self._providers.keys())

    def set_cost_tracker(self, tracker: CostTracker) -> None:
        self._cost_tracker = tracker

    @property
    def cost_tracker(self) -> CostTracker | None:
        return self._cost_tracker

    def create(self, name: str | None = None, settings: Any = None) -> LLMProvider:
        """Create a configured provider instance.

        If name is None, uses settings.default_provider.
        If the provider name is unknown, falls back to LiteLLM when enabled.
        """
        settings = settings or get_settings()
        name = name or settings.default_provider

        self._validate_api_key(name, settings)

        if name not in self._providers:
            if getattr(settings, "litellm_fallback_enabled", False):
                from backend.providers.litellm_provider import LiteLLMProvider

                logger.info("Unknown provider '%s' — routing through LiteLLM", name)
                return LiteLLMProvider(model=name, api_key=settings.openai_api_key)
            raise ValueError(
                f"Unknown provider: {name}. Available: {self.list_providers()}"
            )

        cls = self._providers[name]
        provider = self._construct_provider(cls, name, settings)

        if self._cost_tracker:
            provider.set_cost_callback(self._cost_tracker.record)

        if getattr(settings, "caching_enabled", False):
            provider = _wrap_cached(provider, name, settings)

        if getattr(settings, "resilience_enabled", False):
            provider = _wrap_resilient(provider, name, settings)

        return provider

    def _construct_provider(
        self, cls: type[LLMProvider], name: str, settings: Any
    ) -> LLMProvider:
        """Generic provider constructor. Routes by name to pass the right settings."""
        if name == "openai":
            return cls(
                api_key=settings.openai_api_key,
                model=settings.openai_model,
                embedding_model=settings.embedding_model,
            )
        elif name == "anthropic":
            return cls(
                api_key=settings.anthropic_api_key,
                model=settings.anthropic_model,
                embedding_model=settings.embedding_model,
                base_url=settings.anthropic_base_url,
            )
        elif name == "gemini":
            return cls(
                api_key=settings.gemini_api_key,
                model=settings.gemini_model,
            )
        elif name == "ollama":
            return cls(
                base_url=settings.ollama_base_url,
                model=settings.ollama_model,
            )
        elif name == "litellm":
            return cls(
                model=settings.litellm_model,
                api_key=settings.openai_api_key,
            )
        else:
            return cls()

    @staticmethod
    def _validate_api_key(provider_name: str, settings: Any) -> None:
        _KEY_MAP = {
            "openai": ("openai_api_key", "EROCK_OPENAI_API_KEY"),
            "anthropic": ("anthropic_api_key", "EROCK_ANTHROPIC_API_KEY"),
            "gemini": ("gemini_api_key", "EROCK_GEMINI_API_KEY"),
            "litellm": ("openai_api_key", "EROCK_OPENAI_API_KEY"),
        }
        if provider_name not in _KEY_MAP:
            return
        attr_name, env_var = _KEY_MAP[provider_name]
        value = getattr(settings, attr_name, None)
        if not value or not value.strip():
            raise ProviderConfigurationError(
                detail=f"{env_var} not set",
                hint=(
                    f"Add it to .env or set the environment variable: "
                    f"export {env_var}=sk-... "
                    f"Or switch to a provider that doesn't require a key: ollama"
                ),
            )


# Module-level singleton
_registry: ProviderRegistry | None = None


def _get_registry() -> ProviderRegistry:
    global _registry
    if _registry is None:
        _registry = ProviderRegistry()
    return _registry


def get_registry() -> ProviderRegistry:
    """Get the global provider registry."""
    return _get_registry()


def register_provider(name: str, cls: type[LLMProvider]) -> None:
    """Register a custom provider. Backward-compatible entry point."""
    _get_registry().register(name, cls)


def create_provider(name: str | None = None) -> LLMProvider:
    """Create a configured provider. Drop-in replacement for the old factory."""
    return _get_registry().create(name)


def _validate_api_key(provider_name: str, settings: Any) -> None:
    """Backward-compatible module-level alias."""
    ProviderRegistry._validate_api_key(provider_name, settings)


# ---- Resilience Wiring ----

_vault: KeyVault | None = None


def _get_vault(settings: Any) -> KeyVault | None:
    global _vault
    if _vault is not None:
        return _vault
    if not getattr(settings, "secrets_master_password", None):
        return None
    from backend.providers.secrets import KeyVault

    _vault = KeyVault(
        master_password=settings.secrets_master_password,
        persist_path=f"{settings.secrets_persist_dir}/vault.json",
    )
    try:
        _vault.load()
    except Exception:
        logger.warning("Failed to load key vault — starting fresh")
    return _vault


def _wrap_cached(
    provider: LLMProvider, name: str, settings: Any
) -> LLMProvider:
    from backend.providers.cache import CachedProvider, InMemoryCache, SemanticCache

    cache_type = getattr(settings, "caching_type", "memory")
    max_size = getattr(settings, "caching_max_size", 1000)
    ttl_seconds = getattr(settings, "caching_ttl_seconds", 3600)

    if cache_type == "semantic":
        from backend.pipeline.knowledge.embedding_providers import create_embedding_provider
        from backend.pipeline.knowledge.embedding_service import EmbeddingService

        emb_provider = create_embedding_provider(
            provider_name=getattr(settings, "embedding_provider", "openai"),
            model=getattr(settings, "embedding_model", "text-embedding-3-small"),
            api_key=getattr(settings, "openai_api_key", ""),
            base_url=getattr(settings, "ollama_base_url", "http://localhost:11434"),
            dimension=getattr(settings, "embedding_dimension", 1536) or None,
        )
        emb_service = EmbeddingService(
            emb_provider,
            batch_size=getattr(settings, "embedding_batch_size", 100),
        )
        semantic_cache = SemanticCache(
            embedding_service=emb_service,
            persist_dir=getattr(settings, "caching_persist_dir", "./data/chroma"),
            similarity_threshold=getattr(settings, "caching_similarity_threshold", 0.95),
            ttl_seconds=ttl_seconds,
            max_size=max_size,
        )
        memory_cache = InMemoryCache(max_size=max_size, ttl_seconds=ttl_seconds)
        return CachedProvider(
            wrapped=provider,
            cache=memory_cache,
            cache_type="semantic",
            semantic_cache=semantic_cache,
        )

    memory_cache = InMemoryCache(max_size=max_size, ttl_seconds=ttl_seconds)
    return CachedProvider(wrapped=provider, cache=memory_cache, cache_type="memory")


def _wrap_resilient(
    provider: LLMProvider, name: str, settings: Any
) -> LLMProvider:
    from backend.providers.resilience import CircuitBreaker, ResilientProvider, RetryConfig
    from backend.providers.resilience.circuit_breaker import _breakers

    breaker = _breakers.setdefault(
        name,
        CircuitBreaker(
            failure_threshold=settings.circuit_breaker_failure_threshold,
            reset_timeout=settings.circuit_breaker_reset_timeout,
            cooldown_percent=getattr(settings, "circuit_breaker_cooldown_percent", 0.1),
        ),
    )
    retry_config = RetryConfig(
        max_retries=settings.retry_max_retries,
        base_delay=settings.retry_base_delay,
        max_delay=settings.retry_max_delay,
        cooldown_delay=settings.retry_cooldown_delay,
    )
    vault = _get_vault(settings)
    return ResilientProvider(provider, breaker, retry_config, vault)


# ---- Cost Tracking ----

class CostTracker:
    """Per-provider cost tracking with multi-dimensional aggregation.

    Inspired by Paperclip's cost tracking with 6 aggregation dimensions.
    """

    # Rough per-1K-token costs (USD). Can be overridden per provider/model.
    DEFAULT_COSTS: dict[str, dict[str, float]] = {
        "openai": {"input": 0.0025, "output": 0.01},
        "anthropic": {"input": 0.003, "output": 0.015},
        "gemini": {"input": 0.00125, "output": 0.005},
        "ollama": {"input": 0.0, "output": 0.0},
        "litellm": {"input": 0.0025, "output": 0.01},
    }

    def __init__(self) -> None:
        self._events: list[CostEvent] = []
        self._cost_overrides: dict[str, dict[str, float]] = {}

    def set_cost_per_1k(self, provider: str, input_cost: float, output_cost: float) -> None:
        self._cost_overrides[provider] = {"input": input_cost, "output": output_cost}

    def record(self, event: CostEvent) -> None:
        if event.cost_usd == 0.0:
            rates = self._cost_overrides.get(event.provider, self.DEFAULT_COSTS.get(event.provider, {"input": 0.0, "output": 0.0}))
            event.cost_usd = (
                (event.input_tokens / 1000.0) * rates.get("input", 0.0)
                + (event.output_tokens / 1000.0) * rates.get("output", 0.0)
            )
        self._events.append(event)

    def summary(self) -> dict[str, Any]:
        if not self._events:
            return {"total_cost_usd": 0.0, "total_tokens": 0, "event_count": 0}
        return {
            "total_cost_usd": sum(e.cost_usd for e in self._events),
            "total_tokens": sum(e.total_tokens for e in self._events),
            "total_input_tokens": sum(e.input_tokens for e in self._events),
            "total_output_tokens": sum(e.output_tokens for e in self._events),
            "event_count": len(self._events),
        }

    def by_provider(self) -> dict[str, dict[str, Any]]:
        result: dict[str, dict[str, Any]] = {}
        for e in self._events:
            if e.provider not in result:
                result[e.provider] = {"cost_usd": 0.0, "input_tokens": 0, "output_tokens": 0, "calls": 0}
            r = result[e.provider]
            r["cost_usd"] += e.cost_usd
            r["input_tokens"] += e.input_tokens
            r["output_tokens"] += e.output_tokens
            r["calls"] += 1
        return result

    def by_stage(self) -> dict[str, dict[str, Any]]:
        result: dict[str, dict[str, Any]] = {}
        for e in self._events:
            stage = e.stage or "unspecified"
            if stage not in result:
                result[stage] = {"cost_usd": 0.0, "input_tokens": 0, "output_tokens": 0, "calls": 0}
            r = result[stage]
            r["cost_usd"] += e.cost_usd
            r["input_tokens"] += e.input_tokens
            r["output_tokens"] += e.output_tokens
            r["calls"] += 1
        return result

    def by_model(self) -> dict[str, dict[str, Any]]:
        result: dict[str, dict[str, Any]] = {}
        for e in self._events:
            key = f"{e.provider}/{e.model}"
            if key not in result:
                result[key] = {"cost_usd": 0.0, "input_tokens": 0, "output_tokens": 0, "calls": 0}
            r = result[key]
            r["cost_usd"] += e.cost_usd
            r["input_tokens"] += e.input_tokens
            r["output_tokens"] += e.output_tokens
            r["calls"] += 1
        return result

    def reset(self) -> None:
        self._events.clear()

    def events_in_range(self, start: float, end: float) -> list:
        """Return cost events whose timestamp falls within [start, end] epoch seconds."""
        return [
            e for e in self._events
            if start <= e.timestamp.timestamp() <= end
        ]

    def persist(self, path: str) -> None:
        """Write all cost events to a JSONL file."""
        from pathlib import Path
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            for e in self._events:
                line = json.dumps({
                    "provider": e.provider,
                    "model": e.model,
                    "input_tokens": e.input_tokens,
                    "output_tokens": e.output_tokens,
                    "cost_usd": e.cost_usd,
                    "stage": e.stage,
                    "run_id": e.run_id,
                    "timestamp": e.timestamp.isoformat(),
                })
                f.write(line + "\n")

    @classmethod
    def load(cls, path: str) -> "CostTracker":
        """Load cost events from a JSONL file."""
        tracker = cls()
        from backend.providers.base import CostEvent
        from datetime import datetime, timezone
        with open(path, encoding="utf-8") as f:
            for line in f:
                data = json.loads(line.strip())
                event = CostEvent(
                    provider=data["provider"],
                    model=data["model"],
                    input_tokens=data["input_tokens"],
                    output_tokens=data["output_tokens"],
                    cost_usd=data.get("cost_usd", 0.0),
                    stage=data.get("stage", ""),
                    run_id=data.get("run_id"),
                    timestamp=datetime.fromisoformat(data.get("timestamp", datetime.now(timezone.utc).isoformat())),
                )
                tracker._events.append(event)
        return tracker

"""Pipeline stages — composable units following the ActivationPipeline pattern."""

from __future__ import annotations

import logging
from abc import ABC, abstractmethod
from contextlib import contextmanager
from dataclasses import dataclass, field
from typing import TYPE_CHECKING, Generator

from backend.pipeline.ingestion.chunker import DocumentChunk  # noqa: F401 — re-exported by stages

if TYPE_CHECKING:
    from backend.providers.base import LLMProvider
    from backend.pipeline.result import PipelineResult

logger = logging.getLogger(__name__)


@contextmanager
def _override_provider(
    service: object, override: LLMProvider | None
) -> Generator[None, None, None]:
    """Temporarily swap a service's _provider with the override."""
    if not override or not hasattr(service, "_provider"):
        yield
        return
    saved = service._provider  # type: ignore[attr-defined]
    try:
        service._provider = override  # type: ignore[attr-defined]
        yield
    finally:
        service._provider = saved  # type: ignore[attr-defined]


@dataclass
class StageContext:
    """Shared mutable state passed between stages."""

    result: PipelineResult
    all_papers: list = field(default_factory=list)
    db_run_id: int | None = None
    params: dict = field(default_factory=dict)
    domain: str = "AI/NLP"
    run_id: str = ""
    search_queries: list[str] | None = None
    max_gaps: int = 5
    rounds: int = 2
    ideas_per: int = 3
    export_format: str | None = "markdown"
    provider_override: Any = None  # LLMProvider override for model routing


class PipelineStage(ABC):
    """Base class for pipeline stages."""

    @property
    @abstractmethod
    def name(self) -> str:
        ...

    @abstractmethod
    async def execute(self, ctx: StageContext) -> bool:
        """Execute the stage. Return False to halt the pipeline."""
        ...


class LiteratureSearchStage(PipelineStage):
    def __init__(self, search, hooks):
        self._search = search
        self._hooks = hooks

    @property
    def name(self) -> str:
        return "literature_search"

    async def execute(self, ctx: StageContext) -> bool:
        queries = ctx.search_queries or [
            f"{ctx.domain} recent advances",
            f"{ctx.domain} open problems",
        ]
        all_papers = []
        for query in queries:
            papers = await self._search.search_all(query, limit_per_source=20)
            all_papers.extend(papers)
            logger.info("Found %d papers for query: %s", len(papers), query)

        ctx.all_papers = all_papers
        ctx.result.papers_found = len(all_papers)
        logger.info("Total unique papers: %d", len(all_papers))

        if not all_papers:
            logger.warning("No papers found. Pipeline cannot continue.")
            return False
        return True


class IngestionStage(PipelineStage):
    def __init__(self, store, bm25, embedding, kg=None):
        self._store = store
        self._bm25 = bm25
        self._embedding = embedding
        self._kg = kg

    @property
    def name(self) -> str:
        return "ingestion"

    async def execute(self, ctx: StageContext) -> bool:
        chunks = []
        for paper in ctx.all_papers:
            text = f"{paper.title}\n\n{paper.abstract or ''}"
            paper_chunks = [
                DocumentChunk(
                    text=text,
                    paper_id=paper.id,
                    section="abstract",
                    chunk_index=0,
                )
            ]
            chunks.append(paper_chunks)

        added = await self._store.add_papers(ctx.all_papers, chunks)
        logger.info("Added %d chunks to knowledge base", added)

        all_ids, all_texts, all_metas = [], [], []
        for paper, paper_chunks in zip(ctx.all_papers, chunks, strict=True):
            for j, chunk in enumerate(paper_chunks):
                all_ids.append(f"{paper.id}_chunk_{j}")
                all_texts.append(chunk.text)
                all_metas.append(
                    {
                        "paper_id": paper.id,
                        "paper_title": paper.title[:500],
                        "source": paper.source,
                    }
                )
        if all_ids:
            self._bm25.add_documents(all_ids, all_texts, all_metas)
            logger.info("Synced %d documents to BM25 index", len(all_ids))

        # Write to Knowledge Graph
        if self._kg:
            from backend.pipeline.knowledge.entities import EntityType, KnowledgeEntity
            from backend.pipeline.knowledge.truth import TruthValue

            for paper in ctx.all_papers:
                entity = KnowledgeEntity(
                    id=f"paper:{paper.id}",
                    entity_type=EntityType.PAPER,
                    name=paper.title,
                    properties={
                        "source": paper.source,
                        "year": paper.year,
                        "citation_count": paper.citation_count,
                    },
                    truth=TruthValue.from_observation(frequency=0.9),
                )
                self._kg.add_entity(entity)
            self._kg.save()
            logger.info("Added %d paper entities to Knowledge Graph", len(ctx.all_papers))

        return True


class GapAnalysisStage(PipelineStage):
    def __init__(self, gap_analyzer, goal_manager, hooks, memory, kg=None, faithfulness_checker=None):
        self._gap_analyzer = gap_analyzer
        self._goal_manager = goal_manager
        self._hooks = hooks
        self._memory = memory
        self._kg = kg
        self._faithfulness_checker = faithfulness_checker

    @property
    def name(self) -> str:
        return "gap_analysis"

    async def execute(self, ctx: StageContext) -> bool:
        with _override_provider(self._gap_analyzer, ctx.provider_override):
            return await self._execute_gap_analysis(ctx)

    async def _execute_gap_analysis(self, ctx: StageContext) -> bool:
        prior_gaps = await self._recall_prior_gaps(ctx.domain)
        gaps, cluster_report = await self._gap_analyzer.analyze(
            ctx.all_papers,
            domain=ctx.domain,
            max_gaps=ctx.max_gaps,
            prior_gaps=prior_gaps,
        )
        ctx.result.gaps = gaps
        ctx.result.cluster_report = cluster_report
        logger.info("Identified %d research gaps", len(gaps))

        # Write gaps to Knowledge Graph
        if self._kg:
            from backend.pipeline.knowledge.entities import EntityType, KnowledgeEntity
            from backend.pipeline.knowledge.relationships import KnowledgeRelationship, RelationType
            from backend.pipeline.knowledge.truth import TruthValue

            for gap in gaps:
                gap_entity = KnowledgeEntity(
                    id=f"gap:{gap.title[:60]}",
                    entity_type=EntityType.CONCEPT,
                    name=gap.title,
                    properties={
                        "gap_type": gap.gap_type,
                        "description": gap.description[:200],
                        "potential_impact": gap.potential_impact,
                    },
                    truth=TruthValue(frequency=gap.confidence, confidence=0.6),
                )
                self._kg.add_entity(gap_entity)
            self._kg.save()
            logger.info("Added %d gap entities to Knowledge Graph", len(gaps))

        # Faithfulness check: verify gap claims against source papers
        if self._faithfulness_checker and gaps:
            try:
                reports = await self._faithfulness_checker.check_gap_claims(
                    gaps, ctx.all_papers,
                )
                unfaithful = [r for r in reports if not r.is_faithful]
                if unfaithful:
                    logger.warning(
                        "Faithfulness check: %d/%d gaps have unfaithful claims",
                        len(unfaithful), len(gaps),
                    )
                    for r in unfaithful:
                        logger.warning("  Unfaithful: %s — %s", r.claim[:60], r.explanation[:100])
            except Exception as e:
                logger.warning("Faithfulness check failed: %s", e)

        if self._goal_manager and gaps:
            new_goals = self._goal_manager.create_from_gaps(gaps)
            logger.info("Created %d research goals from gaps", len(new_goals))

        for gap in gaps:
            await self._hooks.dispatch_sync_safe(
                "gap.found",
                {
                    "title": gap.title,
                    "confidence": gap.confidence,
                    "gap_type": gap.gap_type,
                },
            )
        return True

    async def _recall_prior_gaps(self, domain):
        if not self._memory:
            return None
        from backend.pipeline.memory.models import MemoryQuery, MemoryType

        results = await self._memory.recall(
            MemoryQuery(
                query=f"{domain} research gaps",
                memory_type=MemoryType.SEMANTIC,
                namespace="research_facts",
                top_k=20,
            )
        )
        return results if results else None


class IdeaGenerationStage(PipelineStage):
    def __init__(self, agent, hooks, dag_executor=None, dag_agents=None, provider=None, kg=None, forest=None, reasoning_verifier=None):
        self._agent = agent
        self._hooks = hooks
        self._dag_executor = dag_executor
        self._dag_agents = dag_agents
        self._provider = provider
        self._kg = kg
        self._forest = forest
        self._reasoning_verifier = reasoning_verifier

    @property
    def name(self) -> str:
        return "idea_generation"

    async def execute(self, ctx: StageContext) -> bool:
        provider = ctx.provider_override or self._provider
        with _override_provider(self._agent, provider):
            if self._dag_executor is not None:
                return await self._execute_dag(ctx, provider)
            return await self._execute_sequential(ctx)

    async def _execute_sequential(self, ctx: StageContext) -> bool:
        logger.info("Idea Generation (%d rounds, %d ideas/round)", ctx.rounds, ctx.ideas_per)
        ideas = await self._agent.run(
            gaps=ctx.result.gaps,
            context_papers=ctx.all_papers[:30],
            rounds=ctx.rounds,
            ideas_per_round=ctx.ideas_per,
        )
        ctx.result.ideas = ideas
        ctx.result.critique_history = self._agent.last_critique_history
        ctx.result.refinement_history = self._agent.last_refinement_history
        logger.info("Generated %d research ideas", len(ideas))

        # Write ideas to Knowledge Graph
        if self._kg and ideas:
            from backend.pipeline.knowledge.entities import EntityType, KnowledgeEntity
            from backend.pipeline.knowledge.relationships import KnowledgeRelationship, RelationType
            from backend.pipeline.knowledge.truth import TruthValue

            for idea in ideas:
                idea_entity = KnowledgeEntity(
                    id=f"idea:{idea.title[:60]}",
                    entity_type=EntityType.CONCEPT,
                    name=idea.title,
                    properties={
                        "proposed_method": idea.proposed_method[:200],
                        "domain": idea.domain,
                    },
                    truth=TruthValue(frequency=idea.score, confidence=0.5),
                )
                self._kg.add_entity(idea_entity)

                for gap_id in idea.source_gap_ids:
                    gap_eid = f"gap:{gap_id[:60]}"
                    if gap_eid in self._kg._entities:
                        self._kg.add_relationship(KnowledgeRelationship(
                            source_id=gap_eid,
                            target_id=f"idea:{idea.title[:60]}",
                            relation_type=RelationType.PROPOSES_METHOD,
                            truth=TruthValue.from_observation(frequency=idea.score),
                        ))

            self._kg.save()
            logger.info("Added %d idea entities to Knowledge Graph", len(ideas))

        # Reasoning verification on top ideas
        if self._reasoning_verifier and ideas and ctx.result.gaps:
            try:
                for idea in ideas[:5]:
                    gap = ctx.result.gaps[0] if ctx.result.gaps else None
                    if gap:
                        result = await self._reasoning_verifier.verify_idea_reasoning(idea, gap)
                        if not result.passed:
                            logger.warning(
                                "Idea '%s' failed reasoning verification: %s",
                                idea.title[:60], "; ".join(result.issues[:3]),
                            )
            except Exception as e:
                logger.warning("Reasoning verification failed: %s", e)

        for idea in ideas:
            await self._hooks.dispatch_sync_safe(
                "idea.generated",
                {
                    "title": idea.title,
                    "score": idea.score,
                },
            )
        return True

    async def _execute_dag(self, ctx: StageContext, provider=None) -> bool:
        """Execute idea generation via the DAG executor."""
        from backend.pipeline.generation.agent_handlers import register_all_agents
        from backend.pipeline.generation.context_isolator import ContextIsolator
        from backend.pipeline.generation.models import ResearchIdea

        logger.info("Idea Generation via DAG (%d gaps)", len(ctx.result.gaps))

        isolator = ContextIsolator(ctx.result.gaps, ctx.all_papers[:30])

        # Register handlers for this run
        cleanup = register_all_agents(
            registry=self._dag_executor._registry,
            agents=self._dag_agents,
            isolator=isolator,
            provider=provider or self._provider,
        )

        # Prepare input: one item per gap
        dag_input = [
            {"gap": gap, "papers": ctx.all_papers[:30], "n_ideas": ctx.ideas_per}
            for gap in ctx.result.gaps
        ]

        try:
            results = await self._dag_executor.execute(dag_input)
        finally:
            # Restore buffered taxonomies
            for _, buffered, restore in cleanup:
                restore()

        # Extract ResearchIdea objects from results
        ideas = [i for i in results if isinstance(i, ResearchIdea)]
        if not ideas:
            # Try extracting from dicts
            for r in results:
                if isinstance(r, dict) and "ideas" in r:
                    ideas.extend(r["ideas"])

        ctx.result.ideas = ideas
        logger.info("DAG generated %d research ideas", len(ideas))

        for idea in ideas:
            await self._hooks.dispatch_sync_safe(
                "idea.generated",
                {"title": idea.title, "score": idea.score},
            )
        return True


class NoveltyCheckingStage(PipelineStage):
    def __init__(self, novelty_checker, hooks=None):
        self._novelty = novelty_checker
        self._hooks = hooks

    @property
    def name(self) -> str:
        return "novelty_checking"

    async def execute(self, ctx: StageContext) -> bool:
        ideas = ctx.result.ideas
        if not ideas:
            return True
        for i, idea in enumerate(ideas):
            report = await self._novelty.check_novelty(idea)
            ctx.result.novelty_reports[i] = report
            logger.info("Novelty score for '%s': %.2f", idea.title[:50], report.overall_score)

        if self._hooks:
            for i, idea in enumerate(ideas):
                nr = ctx.result.novelty_reports.get(i)
                if nr:
                    await self._hooks.dispatch_sync_safe(
                        "idea.scored",
                        {
                            "title": idea.title,
                            "novelty_score": nr.overall_score,
                        },
                    )
        return True


class FeasibilityScoringStage(PipelineStage):
    def __init__(self, feasibility_scorer):
        self._feasibility = feasibility_scorer

    @property
    def name(self) -> str:
        return "feasibility_scoring"

    async def execute(self, ctx: StageContext) -> bool:
        with _override_provider(self._feasibility, ctx.provider_override):
            return await self._execute_feasibility(ctx)

    async def _execute_feasibility(self, ctx: StageContext) -> bool:
        ideas = ctx.result.ideas
        if not ideas:
            return True
        from backend.config import get_settings
        settings = get_settings()
        for i, idea in enumerate(ideas):
            novelty = ctx.result.novelty_reports.get(i)
            report = await self._feasibility.score_feasibility(idea, novelty)
            # Counterfactual analysis (Gap 14)
            if settings.counterfactual_enabled:
                report = await self._feasibility.run_counterfactual(report)
            ctx.result.feasibility_reports[i] = report
            logger.info(
                "Feasibility score for '%s': %.1f/10", idea.title[:50], report.overall_score
            )
        return True


class ProposalSynthesisStage(PipelineStage):
    def __init__(
        self, synthesizer, governance_validator=None, governance_audit=None, ref_validator=None
    ):
        self._synthesizer = synthesizer
        self._governance_validator = governance_validator
        self._governance_audit = governance_audit
        self._ref_validator = ref_validator

    @property
    def name(self) -> str:
        return "proposal_synthesis"

    async def execute(self, ctx: StageContext) -> bool:
        with _override_provider(self._synthesizer, ctx.provider_override):
            return await self._execute_synthesis(ctx)

    async def _execute_synthesis(self, ctx: StageContext) -> bool:
        ideas = ctx.result.ideas
        if not ideas:
            return True
        for i, idea in enumerate(ideas):
            novelty = ctx.result.novelty_reports.get(i)
            feasibility = ctx.result.feasibility_reports.get(i)
            proposal = await self._synthesizer.synthesize(
                idea=idea,
                novelty_report=novelty,
                feasibility_report=feasibility,
                supporting_papers=ctx.all_papers[:10],
                gaps=ctx.result.gaps,
            )

            if self._governance_validator:
                proposal_md = proposal.to_markdown()
                validated_text, checks = await self._governance_validator.validate_with_reask(
                    proposal_md,
                    output_type="proposal",
                )
                proposal.sections["validated_text"] = validated_text

                if self._governance_audit:
                    from backend.pipeline.governance.events import (
                        GovernanceAuditLog,
                        GovernanceEvent,
                    )

                    verdict = (
                        "accepted"
                        if all(c.verdict.value != "rejected" for c in checks)
                        else "revised"
                    )
                    self._governance_audit.record(
                        GovernanceEvent(
                            event_type=f"output.{verdict}",
                            stage="proposal_synthesis",
                            content_hash=GovernanceAuditLog.content_hash(proposal_md),
                            checks_summary=f"{len(checks)} checks, verdict={verdict}",
                        )
                    )

            ctx.result.proposals[i] = proposal
            logger.info("Generated proposal for idea %d: %s", i + 1, idea.title[:50])

            # Reference validation
            if self._ref_validator:
                refs = proposal.sections.get("references", [])
                if isinstance(refs, list) and refs:
                    validation_results = await self._ref_validator.validate(refs)
                    proposal.sections["reference_validation"] = [
                        {"index": v.reference_index, "title": v.title, "status": v.status}
                        for v in validation_results
                    ]
                    unverified = sum(1 for v in validation_results if v.status == "unverified")
                    if unverified:
                        logger.info(
                            "Proposal %d: %d/%d references unverified",
                            i + 1,
                            unverified,
                            len(refs),
                        )
        return True


class ExportStage(PipelineStage):
    def __init__(self, export_service):
        self._export = export_service

    @property
    def name(self) -> str:
        return "export"

    async def execute(self, ctx: StageContext) -> bool:
        if ctx.export_format and ctx.result.proposals:
            for i, proposal in ctx.result.proposals.items():
                path = await self._export.export(proposal, format=ctx.export_format)
                ctx.result.export_paths[i] = path
                logger.info("Exported proposal to: %s", path)
        return True

"""Proposal synthesis — generate structured research proposals."""

import logging
from pathlib import Path

from jinja2 import Template

from backend.pipeline.feasibility.feasibility_scorer import FeasibilityReport
from backend.pipeline.generation.models import ResearchIdea
from backend.pipeline.literature.models import Paper
from backend.pipeline.novelty.novelty_checker import NoveltyReport
from backend.providers.base import LLMProvider

logger = logging.getLogger(__name__)

PROMPT_DIR = Path(__file__).parent / "prompts"


class ResearchProposal:
    def __init__(self, idea_id: int | None = None, **sections):
        self.idea_id = idea_id
        self.sections = sections

    @property
    def title(self) -> str:
        return self.sections.get("title", "Untitled Proposal")

    @property
    def abstract(self) -> str:
        return self.sections.get("abstract", "")

    def to_markdown(self) -> str:
        """Convert proposal to Markdown format."""
        md_parts = []
        for key, value in self.sections.items():
            if key == "references":
                md_parts.append("## References\n")
                for i, ref in enumerate(value if isinstance(value, list) else [value], 1):
                    if isinstance(ref, dict):
                        authors = ref.get("authors", "Unknown")
                        year = ref.get("year", "n.d.")
                        title = ref.get("title", "Untitled")
                        venue = ref.get("venue", "")
                        doi = ref.get("doi", "")
                        url = ref.get("url", "")
                        line = f"[{i}] {authors} ({year}). {title}."
                        if venue:
                            line += f" {venue}."
                        if doi:
                            line += f" DOI: {doi}"
                        elif url:
                            line += f" URL: {url}"
                        md_parts.append(line)
                    else:
                        md_parts.append(f"- {ref}")
            elif key == "evaluation_plan" and isinstance(value, dict):
                header = key.replace("_", " ").title()
                md_parts.append(f"## {header}\n")
                for sub_key, sub_val in value.items():
                    sub_header = sub_key.replace("_", " ").title()
                    if isinstance(sub_val, list):
                        md_parts.append(f"**{sub_header}**: " + ", ".join(str(v) for v in sub_val))
                    else:
                        md_parts.append(f"**{sub_header}**: {sub_val}")
            elif isinstance(value, str):
                header = key.replace("_", " ").title()
                md_parts.append(f"## {header}\n\n{value}")
            elif isinstance(value, dict):
                header = key.replace("_", " ").title()
                md_parts.append(f"## {header}\n")
                for sub_key, sub_val in value.items():
                    sub_header = sub_key.replace("_", " ").title()
                    md_parts.append(f"**{sub_header}**: {sub_val}")
        return "\n\n".join(md_parts)


class ProposalSynthesizer:
    def __init__(self, provider: LLMProvider, ensemble_reviewer=None):
        self._provider = provider
        self._ensemble_reviewer = ensemble_reviewer
        self._prompt_template = (PROMPT_DIR / "synthesis_system.md").read_text()

    async def synthesize(
        self,
        idea: ResearchIdea,
        novelty_report: NoveltyReport | None = None,
        feasibility_report: FeasibilityReport | None = None,
        supporting_papers: list[Paper] | None = None,
        gaps: list | None = None,
    ) -> ResearchProposal:
        """Generate a structured research proposal."""
        literature = self._format_literature(supporting_papers or [])
        key_risks = feasibility_report.key_risks if feasibility_report else []

        gap_descriptions = ""
        if gaps:
            gap_lines = []
            for g in gaps[:8]:
                gap_lines.append(
                    f"- **{g.title}** (confidence: {g.confidence:.2f}, type: {g.gap_type}): "
                    f"{g.description}"
                )
            gap_descriptions = "\n".join(gap_lines)

        closest_matches = ""
        if novelty_report and novelty_report.closest_matches:
            match_lines = []
            for m in novelty_report.closest_matches[:5]:
                title = m.get("title", "Unknown")
                dist = m.get("distance", "N/A")
                abstract = m.get("abstract", "")
                line = f"- **{title}** (distance: {dist})"
                if abstract:
                    line += f"\n  Abstract: {abstract}"
                match_lines.append(line)
            closest_matches = "\n".join(match_lines)

        feasibility_reasoning = ""
        if feasibility_report:
            feasibility_reasoning = (
                f"Overall feasibility: {feasibility_report.overall_score:.1f}/10\n"
                f"Reasoning: {feasibility_report.reasoning}\n"
                f"Sub-scores: data={feasibility_report.data_availability:.1f}, "
                f"compute={feasibility_report.computational_requirements:.1f}, "
                f"methods={feasibility_report.methodological_complexity:.1f}, "
                f"eval={feasibility_report.evaluation_plan:.1f}, "
                f"novelty_grounding={feasibility_report.novelty_grounding:.1f}, "
                f"impact={feasibility_report.impact_potential:.1f}"
            )

        prompt = Template(self._prompt_template).render(
            title=idea.title,
            problem=idea.problem_statement,
            method=idea.proposed_method,
            contributions=idea.expected_contributions,
            evaluation=idea.evaluation_approach,
            novelty_arguments=novelty_report.novelty_arguments
            if novelty_report
            else "Not assessed",
            timeline=feasibility_report.estimated_timeline if feasibility_report else "3-6 months",
            risks="; ".join(key_risks) if key_risks else "Not assessed",
            key_risks=key_risks,
            literature=literature,
            gap_descriptions=gap_descriptions,
            closest_matches=closest_matches,
            feasibility_reasoning=feasibility_reasoning,
        )

        try:
            result = await self._provider.structured_output(
                messages=[
                    {
                        "role": "system",
                        "content": "You are an expert AI/NLP research proposal writer.",
                    },
                    {"role": "user", "content": prompt},
                ],
                schema={
                    "type": "object",
                    "properties": {
                        "title": {"type": "string"},
                        "abstract": {"type": "string"},
                        "introduction": {"type": "string"},
                        "related_work": {"type": "string"},
                        "proposed_method": {"type": "string"},
                        "expected_contributions": {"type": "string"},
                        "evaluation_plan": {
                            "type": "object",
                            "properties": {
                                "datasets": {"type": "array", "items": {"type": "string"}},
                                "baselines": {"type": "array", "items": {"type": "string"}},
                                "metrics": {"type": "array", "items": {"type": "string"}},
                                "ablation_design": {"type": "string"},
                                "summary": {"type": "string"},
                            },
                        },
                        "timeline": {"type": "string"},
                        "references": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "properties": {
                                    "authors": {"type": "string"},
                                    "year": {"type": "integer"},
                                    "title": {"type": "string"},
                                    "venue": {"type": "string"},
                                    "doi": {"type": "string"},
                                    "url": {"type": "string"},
                                },
                            },
                        },
                        "risk_mitigation": {"type": "string"},
                    },
                    "required": ["title", "abstract", "introduction", "proposed_method"],
                },
                temperature=0.4,
            )
            proposal = ResearchProposal(**result)

            # Quality gate — retry once if sections are too short
            if not self._check_quality(proposal)[0]:
                augmented_prompt = prompt + (
                    "\n\nIMPORTANT: Your previous attempt had sections that were too short. "
                    "Ensure abstract is at least 150 words, introduction at least 100 words, "
                    "and proposed_method at least 100 words."
                )
                try:
                    result2 = await self._provider.structured_output(
                        messages=[
                            {
                                "role": "system",
                                "content": "You are an expert AI/NLP research proposal writer.",
                            },
                            {"role": "user", "content": augmented_prompt},
                        ],
                        schema={
                            "type": "object",
                            "properties": {
                                "title": {"type": "string"},
                                "abstract": {"type": "string"},
                                "introduction": {"type": "string"},
                                "related_work": {"type": "string"},
                                "proposed_method": {"type": "string"},
                                "expected_contributions": {"type": "string"},
                                "evaluation_plan": {
                                    "type": "object",
                                    "properties": {
                                        "datasets": {"type": "array", "items": {"type": "string"}},
                                        "baselines": {"type": "array", "items": {"type": "string"}},
                                        "metrics": {"type": "array", "items": {"type": "string"}},
                                        "ablation_design": {"type": "string"},
                                        "summary": {"type": "string"},
                                    },
                                },
                                "timeline": {"type": "string"},
                                "references": {
                                    "type": "array",
                                    "items": {
                                        "type": "object",
                                        "properties": {
                                            "authors": {"type": "string"},
                                            "year": {"type": "integer"},
                                            "title": {"type": "string"},
                                            "venue": {"type": "string"},
                                            "doi": {"type": "string"},
                                            "url": {"type": "string"},
                                        },
                                    },
                                },
                                "risk_mitigation": {"type": "string"},
                            },
                            "required": ["title", "abstract", "introduction", "proposed_method"],
                        },
                        temperature=0.4,
                    )
                    proposal2 = ResearchProposal(**result2)
                    if self._check_quality(proposal2)[0]:
                        return proposal2
                except Exception:
                    pass

            # Ensemble review (Gap 6)
            if self._ensemble_reviewer:
                try:
                    review_result = await self._ensemble_reviewer.review(proposal, idea)
                    proposal.sections["ensemble_review"] = review_result
                except Exception as e:
                    logger.warning("Ensemble review failed: %s", e)

            return proposal

        except Exception as e:
            logger.error("Proposal synthesis failed: %s", e)
            return ResearchProposal(
                title=idea.title,
                abstract=idea.problem_statement,
                introduction="Synthesis failed. Manual writing required.",
                proposed_method=idea.proposed_method,
            )

    @staticmethod
    def _format_literature(papers: list[Paper]) -> str:
        if not papers:
            return "No specific supporting papers provided."
        lines = []
        for p in papers[:15]:
            authors = ", ".join(a.name for a in p.authors[:3])
            if len(p.authors) > 3:
                authors += " et al."
            line = f"- {authors} ({p.year or 'n.d.'}). {p.title}. {p.venue or 'Unknown venue'}."
            if p.doi:
                line += f" DOI: {p.doi}."
            elif p.url:
                line += f" URL: {p.url}."
            if p.arxiv_id:
                line += f" arXiv: {p.arxiv_id}."
            if p.abstract:
                line += f"\n  Abstract: {p.abstract[:200]}"
            lines.append(line)
        return "\n".join(lines)

    @staticmethod
    def _check_quality(proposal: ResearchProposal) -> tuple[bool, list[str]]:
        """Validate proposal section lengths. Returns (pass, issues)."""
        issues = []
        min_words = {"abstract": 50, "introduction": 100, "proposed_method": 100}
        for section, threshold in min_words.items():
            text = proposal.sections.get(section, "")
            if len(text.split()) < threshold:
                issues.append(f"{section} has fewer than {threshold} words")
        return len(issues) == 0, issues

